-- Eight original recipes bundled with the iPhone app. Exact stable IDs and
-- complete ingredient/step data support authoritative shared tickets immediately.
-- Recipe photos stay bundled in iOS; no third-party media is copied to this cache.
begin;
insert into public.recipes_cache(id,title,cuisine_tag,provider,prep_time_minutes,base_servings,ingredients_json,steps_json,is_fully_hydrated) values
('bulgogi','Weeknight bulgogi bowls','Korean inspired','order_home_original',35,4,'[{"name":"Thinly sliced sirloin","unit":"g","id":"bulgogi-beef","amount":600},{"name":"Dry jasmine rice","unit":"g","id":"bulgogi-rice","amount":300},{"name":"Water for rice","unit":"ml","id":"bulgogi-water","amount":450},{"name":"Soy sauce","unit":"tbsp","id":"bulgogi-soy","amount":4},{"name":"Brown sugar","unit":"tbsp","id":"bulgogi-sugar","amount":2},{"name":"Toasted sesame oil","unit":"tbsp","id":"bulgogi-sesame","amount":1},{"name":"Garlic, minced","unit":"cloves","id":"bulgogi-garlic","amount":3},{"name":"Fresh ginger, grated","unit":"tsp","id":"bulgogi-ginger","amount":2},{"name":"Neutral cooking oil","unit":"tbsp","id":"bulgogi-oil","amount":1},{"name":"Cucumber, sliced","unit":"","id":"bulgogi-cucumber","amount":1},{"name":"Scallions, sliced","unit":"","id":"bulgogi-scallion","amount":3},{"name":"Sesame seeds","unit":"tsp","id":"bulgogi-seeds","amount":2}]'::jsonb,'[{"timerSeconds":900,"id":"bulgogi-step-1","instruction":"Stir the soy sauce, brown sugar, sesame oil, garlic and ginger together. Toss with the sliced beef and refrigerate while you start the rice.","title":"Mix the marinade"},{"timerSeconds":720,"id":"bulgogi-step-2","instruction":"Rinse the rice until the water runs mostly clear. Add the measured water to a saucepan with the rice. Bring to a boil, cover, reduce to very low heat and simmer for 12 minutes. Remove from the heat and leave covered for 5 minutes.","title":"Cook fluffy rice"},{"id":"bulgogi-step-3","instruction":"Slice the cucumber and scallions. Keep them on a clean board away from the raw beef. Set out bowls and sesame seeds.","title":"Get the toppings ready"},{"timerSeconds":180,"id":"bulgogi-step-4","instruction":"Heat the neutral oil in a large skillet over medium-high heat. Lift the beef out of its marinade and sear in a single layer, working in batches, for about 2–3 minutes per side until browned and cooked through. Discard the leftover raw marinade.","title":"Sear in small batches"},{"id":"bulgogi-step-5","instruction":"Fluff the rice and divide it between the bowls. Add the beef, cucumber, scallions and sesame seeds. Serve right away.","title":"Build your bowls"}]'::jsonb,true),
('pasta','Creamy tomato rigatoni','Italian inspired','order_home_original',25,4,'[{"name":"Dry rigatoni","unit":"g","id":"pasta-rigatoni","amount":400},{"name":"Olive oil","unit":"tbsp","id":"pasta-oil","amount":2},{"name":"Small onion, finely diced","unit":"","id":"pasta-onion","amount":1},{"name":"Garlic, minced","unit":"cloves","id":"pasta-garlic","amount":3},{"name":"Crushed tomatoes","unit":"g","id":"pasta-tomato","amount":600},{"name":"Heavy cream","unit":"ml","id":"pasta-cream","amount":120},{"name":"Parmesan, grated","unit":"g","id":"pasta-parmesan","amount":60},{"name":"Fresh basil","unit":"g","id":"pasta-basil","amount":10},{"name":"Fine salt, plus pasta-water salt","unit":"tsp","id":"pasta-salt","amount":0.5},{"name":"Black pepper","unit":"tsp","id":"pasta-pepper","amount":0.25}]'::jsonb,'[{"id":"pasta-step-1","instruction":"Bring a large pot of salted water to a boil. Add the rigatoni and cook for the time on the packet, checking a minute early for a firm center. Reserve a mug of cooking water before draining.","title":"Put the pasta on"},{"timerSeconds":300,"id":"pasta-step-2","instruction":"Meanwhile, warm the olive oil in a wide saucepan over medium heat. Add the onion and cook for 5 minutes until soft, stirring often. Stir in the garlic and cook for 30 seconds.","title":"Soften the aromatics"},{"timerSeconds":600,"id":"pasta-step-3","instruction":"Add the crushed tomatoes, measured salt and pepper. Bring to a gentle simmer and cook uncovered for 10 minutes, stirring occasionally.","title":"Simmer the tomatoes"},{"id":"pasta-step-4","instruction":"Reduce the heat to low. Stir in the cream and half the Parmesan. Add the drained pasta and a splash of reserved cooking water; toss until the sauce coats every ridge. Add more cooking water a little at a time if needed.","title":"Make it silky"},{"id":"pasta-step-5","instruction":"Taste and adjust the seasoning. Tear the basil over the pasta and finish with the remaining Parmesan. Spoon into warm bowls.","title":"Bring everyone to the table"}]'::jsonb,true),
('pizza','Friday-night margherita','Italian inspired','order_home_original',30,4,'[{"name":"Prepared pizza dough","unit":"g","id":"pizza-dough","amount":600},{"name":"Flour for dusting","unit":"tbsp","id":"pizza-flour","amount":2},{"name":"Passata","unit":"g","id":"pizza-tomato","amount":200},{"name":"Low-moisture mozzarella, torn","unit":"g","id":"pizza-mozzarella","amount":250},{"name":"Olive oil","unit":"tbsp","id":"pizza-oil","amount":1},{"name":"Dried oregano","unit":"tsp","id":"pizza-oregano","amount":1},{"name":"Fine salt","unit":"tsp","id":"pizza-salt","amount":0.25},{"name":"Fresh basil","unit":"g","id":"pizza-basil","amount":10}]'::jsonb,'[{"timerSeconds":900,"id":"pizza-step-1","instruction":"Heat the oven to 475°F / 245°C with two sturdy baking sheets inside. Let the dough rest at room temperature for 15 minutes so it stretches easily. Keep parchment and oven mitts ready.","title":"Heat the oven"},{"id":"pizza-step-2","instruction":"Lightly flour the worktop. Divide the dough into two equal pieces for four servings, adding more pizzas for larger tables. Stretch each piece into a thin round on baking parchment, leaving a slightly thicker rim.","title":"Stretch your bases"},{"id":"pizza-step-3","instruction":"Stir the oregano and salt into the passata. Spread a thin layer over each base, leaving the rim clear. Scatter with mozzarella and drizzle with olive oil.","title":"Make it yours"},{"timerSeconds":720,"id":"pizza-step-4","instruction":"Carefully slide the pizzas and parchment onto the hot baking sheets. Bake for 10–14 minutes, swapping shelves halfway, until the cheese bubbles and the bases and edges are golden. Follow your parchment''s maximum heat rating; use lightly oiled sheets if needed.","title":"Bake until golden"},{"timerSeconds":120,"id":"pizza-step-5","instruction":"Rest for 2 minutes, scatter with torn basil and slice. Bring the pizzas to the table while the edges are still crisp.","title":"Finish with basil"}]'::jsonb,true),
('tacos','Smoky chicken tacos','Mexican inspired','order_home_original',25,4,'[{"name":"Boneless chicken thighs","unit":"g","id":"tacos-chicken","amount":600},{"name":"Olive oil","unit":"tbsp","id":"tacos-oil","amount":1},{"name":"Smoked paprika","unit":"tsp","id":"tacos-paprika","amount":2},{"name":"Ground cumin","unit":"tsp","id":"tacos-cumin","amount":1},{"name":"Fine salt","unit":"tsp","id":"tacos-salt","amount":0.5},{"name":"Small corn tortillas","unit":"","id":"tacos-tortilla","amount":12},{"name":"Avocados","unit":"","id":"tacos-avocado","amount":2},{"name":"Red cabbage, finely shredded","unit":"g","id":"tacos-cabbage","amount":150},{"name":"Plain Greek yogurt","unit":"g","id":"tacos-yogurt","amount":120},{"name":"Limes","unit":"","id":"tacos-lime","amount":2},{"name":"Fresh cilantro","unit":"g","id":"tacos-cilantro","amount":15}]'::jsonb,'[{"id":"tacos-step-1","instruction":"Pat the chicken dry and cut into bite-size strips on a dedicated raw-meat board. Toss with the oil, smoked paprika, cumin and salt. Wash your hands and clean the board and knife before preparing the toppings.","title":"Season the chicken"},{"timerSeconds":540,"id":"tacos-step-2","instruction":"Heat a large skillet over medium-high heat. Cook the chicken in a single layer for 8–10 minutes, turning regularly, until browned and the thickest piece reaches 165°F / 74°C. Work in batches for larger portions.","title":"Cook until juicy"},{"id":"tacos-step-3","instruction":"Slice the avocado, shred the cabbage and chop the cilantro. Stir the juice of half the limes into the yogurt. Cut the remaining limes into wedges.","title":"Prep the toppings"},{"id":"tacos-step-4","instruction":"Warm the tortillas in a dry skillet for about 20 seconds per side. Stack them in a clean towel to keep them soft.","title":"Warm the tortillas"},{"id":"tacos-step-5","instruction":"Put the chicken, tortillas and toppings on the table. Fill each tortilla with chicken, crunchy cabbage, avocado and lime yogurt. Finish with cilantro and a squeeze of lime.","title":"Everyone builds their own"}]'::jsonb,true),
('salmon','Lemon-butter salmon','Fresh & simple','order_home_original',30,4,'[{"name":"Salmon fillets","unit":"g","id":"salmon-fish","amount":600},{"name":"Baby potatoes, halved","unit":"g","id":"salmon-potato","amount":600},{"name":"Green beans, trimmed","unit":"g","id":"salmon-beans","amount":400},{"name":"Olive oil","unit":"tbsp","id":"salmon-oil","amount":2},{"name":"Butter, softened","unit":"g","id":"salmon-butter","amount":40},{"name":"Lemon","unit":"","id":"salmon-lemon","amount":1},{"name":"Garlic, minced","unit":"cloves","id":"salmon-garlic","amount":2},{"name":"Fine salt","unit":"tsp","id":"salmon-salt","amount":0.75},{"name":"Black pepper","unit":"tsp","id":"salmon-pepper","amount":0.25},{"name":"Fresh parsley, chopped","unit":"g","id":"salmon-parsley","amount":10}]'::jsonb,'[{"timerSeconds":900,"id":"salmon-step-1","instruction":"Heat the oven to 425°F / 220°C. Toss the halved baby potatoes with half the oil and half the salt on a large baking tray. Roast cut-side down for 15 minutes.","title":"Give the potatoes a head start"},{"id":"salmon-step-2","instruction":"Mix the softened butter with the garlic, lemon zest and half the lemon juice. Pat the salmon dry and spread the butter over it. Season with the remaining salt and the pepper.","title":"Mix lemon butter"},{"id":"salmon-step-3","instruction":"Toss the green beans with the remaining oil. Move the potatoes to one side of the tray, add the beans and place the salmon skin-side down in the remaining space. Use a second tray if crowded.","title":"Add the salmon and greens"},{"timerSeconds":720,"id":"salmon-step-4","instruction":"Roast for 10–14 minutes until the salmon reaches 145°F / 63°C in the thickest part and the potatoes are tender. Check early for thin fillets and continue cooking if needed.","title":"Roast gently"},{"id":"salmon-step-5","instruction":"Squeeze over the remaining lemon juice and scatter with parsley. Serve each plate with salmon, crisp potatoes, green beans and a spoonful of the tray juices.","title":"Finish bright"}]'::jsonb,true),
('soup','Cozy tortilla soup','Mexican inspired','order_home_original',30,4,'[{"name":"Olive oil","unit":"tbsp","id":"soup-oil","amount":1},{"name":"Onion, diced","unit":"","id":"soup-onion","amount":1},{"name":"Garlic, minced","unit":"cloves","id":"soup-garlic","amount":3},{"name":"Ground cumin","unit":"tsp","id":"soup-cumin","amount":2},{"name":"Smoked paprika","unit":"tsp","id":"soup-paprika","amount":1},{"name":"Canned chopped tomatoes","unit":"g","id":"soup-tomato","amount":800},{"name":"Vegetable stock","unit":"ml","id":"soup-stock","amount":750},{"name":"Black beans, drained","unit":"g","id":"soup-beans","amount":480},{"name":"Frozen sweetcorn","unit":"g","id":"soup-corn","amount":200},{"name":"Lime","unit":"","id":"soup-lime","amount":1},{"name":"Tortilla chips","unit":"g","id":"soup-chips","amount":80},{"name":"Avocado","unit":"","id":"soup-avocado","amount":1},{"name":"Fresh cilantro","unit":"g","id":"soup-cilantro","amount":10}]'::jsonb,'[{"timerSeconds":300,"id":"soup-step-1","instruction":"Warm the olive oil in a large pot over medium heat. Cook the diced onion for 5 minutes until soft. Stir in the garlic, cumin and smoked paprika and cook for 30 seconds.","title":"Build the flavor"},{"timerSeconds":600,"id":"soup-step-2","instruction":"Add the chopped tomatoes and vegetable stock. Bring to a boil, reduce the heat and simmer gently for 10 minutes, stirring occasionally.","title":"Let it bubble"},{"timerSeconds":480,"id":"soup-step-3","instruction":"Rinse the drained black beans and add them with the frozen corn. Simmer for 8 minutes until everything is piping hot. Add a splash of water if the soup is thicker than you like.","title":"Add beans and corn"},{"id":"soup-step-4","instruction":"Dice the avocado, chop the cilantro and break the tortilla chips into large pieces. Squeeze the lime juice into the soup and taste before adding any salt; stock and chips can already be salty.","title":"Get the toppings ready"},{"id":"soup-step-5","instruction":"Ladle into bowls and let everyone add their own avocado, cilantro and crunchy tortilla chips just before eating.","title":"Serve something cozy"}]'::jsonb,true),
('salad','Crispy chickpea bowls','Mediterranean inspired','order_home_original',30,4,'[{"name":"Canned chickpeas, drained","unit":"g","id":"salad-chickpea","amount":480},{"name":"Olive oil","unit":"tbsp","id":"salad-oil","amount":2},{"name":"Smoked paprika","unit":"tsp","id":"salad-paprika","amount":1},{"name":"Fine salt","unit":"tsp","id":"salad-salt","amount":0.5},{"name":"Dry couscous","unit":"g","id":"salad-couscous","amount":240},{"name":"Boiling vegetable stock","unit":"ml","id":"salad-stock","amount":300},{"name":"Cucumber","unit":"","id":"salad-cucumber","amount":1},{"name":"Cherry tomatoes","unit":"g","id":"salad-tomato","amount":250},{"name":"Baby spinach","unit":"g","id":"salad-greens","amount":100},{"name":"Tahini","unit":"tbsp","id":"salad-tahini","amount":3},{"name":"Lemon","unit":"","id":"salad-lemon","amount":1},{"name":"Water for dressing","unit":"tbsp","id":"salad-water","amount":3}]'::jsonb,'[{"timerSeconds":1200,"id":"salad-step-1","instruction":"Heat the oven to 425°F / 220°C. Rinse the chickpeas, pat thoroughly dry and toss with the olive oil, paprika and salt. Spread on a baking tray in a single layer and roast for 20–25 minutes, shaking halfway.","title":"Roast the chickpeas"},{"timerSeconds":300,"id":"salad-step-2","instruction":"Put the couscous in a heatproof bowl. Pour over the boiling stock, cover with a plate and leave for 5 minutes, then fluff with a fork. Check your packet''s water ratio and adjust the stock amount if it differs.","title":"Make fluffy couscous"},{"id":"salad-step-3","instruction":"Dice the cucumber and halve the cherry tomatoes. Wash and dry the spinach. Set everything out so each person can build their own bowl.","title":"Chop the fresh things"},{"id":"salad-step-4","instruction":"Whisk the tahini with the lemon juice. Add the measured water a little at a time until smooth and pourable, adding an extra splash if needed. Taste and adjust the seasoning.","title":"Whisk the dressing"},{"id":"salad-step-5","instruction":"Divide the couscous and spinach between bowls. Add cucumber, tomatoes and hot crispy chickpeas. Drizzle over the lemon tahini just before serving.","title":"Assemble and enjoy"}]'::jsonb,true),
('curry','Coconut chickpea curry','Indian inspired','order_home_original',30,4,'[{"name":"Dry basmati rice","unit":"g","id":"curry-rice","amount":300},{"name":"Water for rice","unit":"ml","id":"curry-water","amount":450},{"name":"Neutral cooking oil","unit":"tbsp","id":"curry-oil","amount":1},{"name":"Onion, diced","unit":"","id":"curry-onion","amount":1},{"name":"Garlic, minced","unit":"cloves","id":"curry-garlic","amount":3},{"name":"Fresh ginger, grated","unit":"tbsp","id":"curry-ginger","amount":1},{"name":"Mild curry powder","unit":"tbsp","id":"curry-powder","amount":2},{"name":"Canned chopped tomatoes","unit":"g","id":"curry-tomato","amount":400},{"name":"Coconut milk","unit":"ml","id":"curry-coconut","amount":400},{"name":"Canned chickpeas, drained","unit":"g","id":"curry-chickpea","amount":480},{"name":"Baby spinach","unit":"g","id":"curry-spinach","amount":150},{"name":"Fine salt","unit":"tsp","id":"curry-salt","amount":0.5},{"name":"Lime","unit":"","id":"curry-lime","amount":1}]'::jsonb,'[{"timerSeconds":720,"id":"curry-step-1","instruction":"Rinse the rice, then place in a saucepan with the measured water. Bring to a boil, cover and reduce the heat to very low. Simmer for 12 minutes, then remove from the heat and rest covered for 5 minutes.","title":"Start the rice"},{"timerSeconds":300,"id":"curry-step-2","instruction":"Heat the oil in a wide saucepan over medium heat. Cook the onion for 5 minutes until soft. Add the garlic and ginger and stir for 1 minute.","title":"Soften the aromatics"},{"id":"curry-step-3","instruction":"Stir in the curry powder and cook for 30 seconds. Add the tomatoes, coconut milk, rinsed chickpeas and salt. Stir well and bring to a gentle simmer.","title":"Bloom the spices"},{"timerSeconds":720,"id":"curry-step-4","instruction":"Simmer uncovered for 12 minutes, stirring occasionally, until the sauce thickens slightly and the chickpeas are hot. Add the spinach in handfuls and stir until wilted.","title":"Make it creamy"},{"id":"curry-step-5","instruction":"Squeeze the lime juice into the curry and taste for seasoning. Fluff the rice and serve with generous spoonfuls of curry. Keep any extra spice on the side for the table.","title":"Finish with lime"}]'::jsonb,true)
on conflict (id) do update set title = excluded.title,cuisine_tag = excluded.cuisine_tag,
  provider = excluded.provider,prep_time_minutes = excluded.prep_time_minutes,
  base_servings = excluded.base_servings,ingredients_json = excluded.ingredients_json,
  steps_json = excluded.steps_json,is_fully_hydrated = excluded.is_fully_hydrated,
  updated_at = now();
commit;
